/**
 * Identifier rules for enrolment and student sign-in.
 *
 * Approved by `docs/ENROLMENT_PERMISSION_MODEL.md` 7 and confirmed by D-019 and
 * D-020. These helpers are pure and isomorphic — no Node-only or database
 * imports — so they can run on the server and be unit-tested without a
 * database.
 *
 * None of these values is a password or proof of account ownership
 * (`docs/ENROLMENT_PERMISSION_MODEL.md` 7.2).
 */

/**
 * Internal student id: the stable, opaque database key. Generated by the
 * platform as a UUID and never user-entered.
 */
const INTERNAL_STUDENT_ID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

export function isInternalStudentId(value: string): boolean {
  return INTERNAL_STUDENT_ID_PATTERN.test(value);
}

/**
 * School code: a readable, globally unique tenant reference used with the
 * username at student sign-in. It is not a secret.
 *
 * The alphabet deliberately omits `I`, `O`, `S` and `Z` to reduce confusion
 * with `1`, `0`, `5` and `2` when a code is read aloud or transcribed
 * (`docs/DECISIONS.md` D-020).
 */
export const SCHOOL_CODE_PATTERN = /^[A-HJ-NP-RT-Y0-9]{4,10}$/;

export function normaliseSchoolCode(value: string): string {
  return value.replace(/[\s-]/g, "").toUpperCase();
}

export function isValidSchoolCode(value: string): boolean {
  return SCHOOL_CODE_PATTERN.test(normaliseSchoolCode(value));
}

/**
 * School registration number: a readable administrative identifier that is
 * unique within its school only, not globally. Normalised (trimmed and
 * upper-cased) so the composite `(school_id, registration_number)` unique
 * constraint is stable regardless of how it was typed.
 */
export const REGISTRATION_NUMBER_MAX_LENGTH = 32;

export function normaliseRegistrationNumber(value: string): string {
  return value.trim().replace(/\s+/g, " ").toUpperCase();
}

export function isValidRegistrationNumber(value: string): boolean {
  const normalised = normaliseRegistrationNumber(value);
  return (
    normalised.length >= 1 &&
    normalised.length <= REGISTRATION_NUMBER_MAX_LENGTH
  );
}

/**
 * The reserved domain used for internal Supabase Auth identities.
 *
 * `.invalid` is reserved by RFC 2606 and can never be registered, delegated or
 * delivered to, so it is provably non-deliverable. It must pass Supabase's
 * email-format validation before the portal slice is implemented (D-020,
 * `docs/PHASE0_RISK_REGISTER.md` R-08).
 */
export const RESERVED_ACCOUNT_DOMAIN = "students.invalid";

/**
 * Builds the internal Supabase Auth identifier for a student account. The value
 * is opaque (derived from the random internal student id, never from the
 * student's name, registration number or username) and must never be presented
 * to a user as an email address or used for delivery.
 */
export function buildInternalAccountIdentifier(
  internalStudentId: string,
): string {
  if (!isInternalStudentId(internalStudentId)) {
    throw new Error(
      "Cannot build an internal account identifier from an invalid internal student id",
    );
  }
  return `${internalStudentId.toLowerCase()}@${RESERVED_ACCOUNT_DOMAIN}`;
}

export function isReservedAccountIdentifier(value: string): boolean {
  const separator = value.lastIndexOf("@");
  if (separator < 1) {
    return false;
  }
  const domain = value.slice(separator + 1).toLowerCase();
  return (
    domain === RESERVED_ACCOUNT_DOMAIN &&
    isInternalStudentId(value.slice(0, separator))
  );
}
